{"requirements": [
{"id": "R-SOC", "parent": "SN-1", "value": 2.97, "unit": "%", "basis": "Gross energy over the 90% window is 4.9311+0.071=5.0021 MWh. 4.600 MWh net needs 4.671 MWh gross, which is an 84.04% window. The 5.96% SOC margin is shared between the top and bottom ends, so each end can carry at most 2.98%."},
{"id": "R-TRIP", "parent": "SN-4", "value": 150, "unit": "ms", "basis": "The cell manufacturer requires disconnection within 150 ms above 3.75 V. The budget is 5 chain scans, plus one MCU control cycle, plus the contactor opening time."},
{"id": "R-PRE", "parent": "SN-3", "value": 9.5, "unit": "s", "basis": "The 10 s DC-bus-ready limit minus the 0.5 s start sequence before precharge leaves 9.5 s."},
{"id": "R-BAL", "parent": "SN-1", "value": 75.4, "unit": "mA", "basis": "Self-discharge spread at 35 C is 1.72% per month, or 0.0573% per day of 263.2 Ah, which is 150.9 mAh per day. Balancing runs 2 h per day, so 75.4 mA is needed."},
{"id": "R-BRK", "parent": ["SN-4", "SN-6"], "value": 950, "unit": "A", "basis": "Cell 2C to 3C limits are 64.6 s and 8.59 s. The 250 A fuse is slower than the cell limit below about 3C, which is about 940 A. The contactor must therefore break from the 345 A trip up to about 950 A, and the fuse covers anything above."},
{"id": "R-RIDE", "parent": "SN-6", "value": 2.04, "unit": "s", "basis": "In the reclose sequence the voltage stays below 50% from t=0 until 1.0+1.0588=2.059 s. The supply's own 20 ms hold-up is subtracted, leaving about 2.04 s to be bridged."},
{"id": "R-IMD", "parent": ["SN-4", "SN-6"], "value": 149.2, "unit": "uF", "basis": "The transformerless PCS units and the unearthed star point make the plant one IT system. Total leakage capacitance is 19x1.52 + 4x30 + 19x2x40 m x 0.19 nF/m = 28.88+120+0.29 = 149.2 uF."}
],
"afe": "AFE-4", "afe_per_module": 1, "chains_per_rack": 2, "current_sensor": "CS-9", "mcu": "MCU-3", "string_contactor": "K-1", "precharge_resistor": "PR-43", "balancing": "internal", "hold_up": "HB-1", "imd_location": "plant", "imd": "IMD-2"}

{"requirements": [
{"id": "R-SOC", "parent": "SN-1", "value": 18.6, "unit": "%", "basis": "3.300/5.632 MWh needs 52.7% of the 90% SOC window; the 37.3% spare is split between the two window ends, so 18.6% per end."},
{"id": "R-TRIP", "parent": "SN-4", "value": 100, "unit": "ms", "basis": "Cell limit is disconnection within 100 ms above 3.75 V. This covers 4 chain scans, one MCU cycle and the contactor opening time."},
{"id": "R-PRE", "parent": "SN-3", "value": 7.5, "unit": "s", "basis": "8 s to DC bus ready minus the 0.5 s start sequence."},
{"id": "R-BAL", "parent": "SN-1", "value": 9.4, "unit": "mA", "basis": "0.9%/month spread at 35 C of 251.1 Ah is 2.26 Ah, balanced in 8 h/day x 30 d = 240 h."},
{"id": "R-BRK", "parent": "SN-4", "value": 2850, "unit": "A", "basis": "The 400 A gBat fuse alone meets the cell short-time limit only above about 2850 A (7.1x), so the contactor must break everything below that."},
{"id": "R-RIDE", "parent": "SN-6", "value": 2.09, "unit": "s", "basis": "The voltage stays below 50% from t=0 to 2.111 s (0.25 s dip, 0.5 s recovery, reclose, 0.25 s dip, 50% reached 1.111 s into the second recovery). Subtract the supply's own 20 ms hold-up."},
{"id": "R-IMD", "parent": ["SN-4", "SN-6"], "value": 172.8, "unit": "uF", "basis": "All racks and PCS units are galvanically coupled in one unearthed system: 23x1.63 + 3x45 + 23x80 m x 0.18 nF/m = 37.5 + 135 + 0.33 uF."}
],
